package net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AutoApproveRegisteredUsersVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property auto approve registered users of tenant config ")
  void test_auto_approve_registered_users_v_o_builder() {
    Assertions.assertFalse(AutoApproveRegisteredUsersVO.nullValue().isAutoApproveRegisteredUsers(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        AutoApproveRegisteredUsersVO.tryFrom(null).isAutoApproveRegisteredUsers(),
        "With a null value, no present result");
    Assertions.assertEquals(true,
        AutoApproveRegisteredUsersVO.from(true).isAutoApproveRegisteredUsers());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AutoApproveRegisteredUsersVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", AutoApproveRegisteredUsersVO.from(true).toString());
  }
}
